import{_ as o,o as t,c as a,a3 as d}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"主题、样式与国际化","description":"","frontmatter":{},"headers":[],"relativePath":"cosmos/basic-app/frontend/theming-i18n.md","filePath":"cosmos/basic-app/frontend/theming-i18n.md","lastUpdated":1785868852000}'),c={name:"cosmos/basic-app/frontend/theming-i18n.md"};function s(i,e,n,r,l,h){return t(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="主题、样式与国际化" tabindex="-1">主题、样式与国际化 <a class="header-anchor" href="#主题、样式与国际化" aria-label="Permalink to &quot;主题、样式与国际化&quot;">​</a></h1><p>外观（Tailwind v4 + 动态取色）与文案（vue-i18n + 后端枚举元数据 + 时区）这两块的约定与陷阱。</p><h2 id="样式-tailwind-css-4-css-first" tabindex="-1">样式：Tailwind CSS 4（CSS-first） <a class="header-anchor" href="#样式-tailwind-css-4-css-first" aria-label="Permalink to &quot;样式：Tailwind CSS 4（CSS-first）&quot;">​</a></h2><p>用 <code>@tailwindcss/vite</code> + <strong>CSS-first <code>@theme</code></strong>（入口 <code>src/styles/index.css</code>），<strong>没有 JS config 文件</strong>。</p><p>三条关键约定：</p><table tabindex="0"><thead><tr><th>约定</th><th>说明</th></tr></thead><tbody><tr><td><strong>只引入 theme + utilities，不引入 preflight</strong></td><td>基础重置由 Naive UI 与 <code>design/global.css</code> 的最小重置负责，避免与 Naive UI 打架</td></tr><tr><td>颜色令牌用运行时 HSL CSS 变量</td><td><code>--color-primary: hsl(var(--primary))</code> 等，保证明暗与主题色能动态切换</td></tr><tr><td>暗色走 class 策略</td><td><code>@custom-variant dark (&amp;:where(.dark, .dark *))</code></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">嵌套 <code>.dark</code> 下 <code>bg-*</code> / <code>text-*</code> 不变暗</p><p><code>@theme</code> 里声明的 <code>--color-*</code> <strong>只在 <code>:root</code> 解析</strong>。深色侧栏、深色子栏、深色顶栏这类<strong>嵌套 <code>.dark</code></strong> 的容器里，Tailwind 的颜色工具类拿不到暗色值，表现是「局部深色区域里的元素还是亮色」。</p><p>修法：在 <code>variables.css</code> 的 <strong><code>:root, .dark</code></strong> 块里<strong>重新声明全部 <code>--color-*</code></strong>，让嵌套作用域也能解析到。</p></div><h2 id="主题" tabindex="-1">主题 <a class="header-anchor" href="#主题" aria-label="Permalink to &quot;主题&quot;">​</a></h2><p><code>useTheme()</code>（<code>~/hooks/useTheme.ts</code>）管理外观：亮/暗/跟随系统、主题色、圆角、字号、紧凑度。</p><p>两个特点：</p><ul><li><strong>Material You 动态取色</strong>：从单个品牌色派生整套和谐色阶（辅色、容器色、前景色、聚焦环、带品牌色相的中性色），明暗自适应，以内联 CSS 变量写到根元素。所以换主题色不需要改任何 CSS。</li><li><strong>切换动画</strong>：<code>startViewTransition</code> 从点击处圆形扩散。</li></ul><p>主色、明暗、圆角、字号变化都会重算并同步到 CSS 变量，非 Naive 的自定义元素也能直接用。</p><p>偏好云端同步：UI 偏好走 <code>UserSettingAppService</code> 按场景 + key 存取，保存后经 SignalR 广播实现<strong>多端同步</strong>（服务端不解释 value，只作跨端状态载体）。</p><h2 id="国际化" tabindex="-1">国际化 <a class="header-anchor" href="#国际化" aria-label="Permalink to &quot;国际化&quot;">​</a></h2><h3 id="语言包组织" tabindex="-1">语言包组织 <a class="header-anchor" href="#语言包组织" aria-label="Permalink to &quot;语言包组织&quot;">​</a></h3><p>vue-i18n（<code>legacy: false</code>），中英双包在 <code>packages/locales/langs/{zh-CN,en-US}/</code>，按模块拆文件（<code>identity.ts</code> / <code>log.ts</code> / <code>message.ts</code> / <code>common.ts</code> / <code>component.ts</code> / <code>menu.ts</code> 等）。</p><p>键名约定 <strong><code>模块.实体.字段或动作</code></strong>，如 <code>identity.user.col_status</code>。</p><p>切换语言：<code>useLocale().setLocale(lang)</code>。</p><h3 id="naive-ui-内置文案" tabindex="-1">Naive UI 内置文案 <a class="header-anchor" href="#naive-ui-内置文案" aria-label="Permalink to &quot;Naive UI 内置文案&quot;">​</a></h3><p>日期选择器、分页「X / 页」这类 Naive 内置文案随应用 locale 切换——<code>App.vue</code> 里 <code>useNaiveLocale()</code> 注入 <code>NConfigProvider</code> 的 <code>locale</code> / <code>date-locale</code>。加新语言时别忘了这一处。</p><h3 id="裸-会白屏" tabindex="-1">裸 <code>@</code> 会白屏 <a class="header-anchor" href="#裸-会白屏" aria-label="Permalink to &quot;裸 \`@\` 会白屏&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>语言包文案里出现<strong>裸 <code>@</code></strong>（如 <code>联系 @admin</code>）会触发 vue-i18n 的 linked message 语法，抛 <code>Invalid linked format</code> 导致<strong>整页白屏</strong>。</p><p>必须转义成 <code>{&#39;@&#39;}</code>：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ❌ 白屏</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">contact</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;联系 @admin&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✅</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">contact</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;联系 {&#39;@&#39;}admin&quot;</span></span></code></pre></div><p>邮箱、社交账号、装饰性符号都是高发区。新增文案前扫一遍。</p></div><h2 id="枚举标签-后端单一事实源" tabindex="-1">枚举标签：后端单一事实源 <a class="header-anchor" href="#枚举标签-后端单一事实源" aria-label="Permalink to &quot;枚举标签：后端单一事实源&quot;">​</a></h2><p>枚举标签的<strong>事实源是后端枚举元数据</strong>（<code>Enums.{culture}.json</code> 全量），按请求头 <code>X-Language</code> 返回当前语言的标签。前端有三条取值路径：</p><table tabindex="0"><thead><tr><th>场景</th><th>用法</th></tr></thead><tbody><tr><td><strong>SchemaPage 字段</strong></td><td>字段声明 <code>dictionaryCode</code>（枚举名或字典码），<code>useSchemaDictionaries</code> 批量拉取注入 <code>field.options</code>；单元格按值映射 label，搜索区自动渲染下拉</td></tr><tr><td><strong>非 Schema 的下拉/标签</strong></td><td><code>useEnumOptions(enumName, fallback)</code>（<code>~/hooks</code>），返回随语言/数据响应式更新的 <code>computed</code></td></tr><tr><td><strong>静态兜底</strong></td><td>元数据为空（未加载/未部署）时回退传入的 <code>fallback</code> 静态选项，<strong>保证绝不出现空下拉</strong></td></tr></tbody></table><h3 id="切语言要响应式" tabindex="-1">切语言要响应式 <a class="header-anchor" href="#切语言要响应式" aria-label="Permalink to &quot;切语言要响应式&quot;">​</a></h3><p>拉取由全局 <code>useEnumService</code> <strong>并发去重</strong>，切 locale 时整库重取一次。<code>useSchemaDictionaries</code> / <code>useEnumOptions</code> 只读响应式状态——<strong>免刷新即随语言更新</strong>，且各下拉不各自监听 locale，避免重复请求。</p><p><code>business.ts</code> 里的 <code>*_OPTIONS</code> 常量是写死中文的，<strong>仅作兜底</strong>，不要当成事实源使用。</p><div class="tip custom-block"><p class="custom-block-title">值要用成员名，不是数字</p><p>后端实例数据经 <code>JsonStringEnumConverter</code> 序列化为<strong>成员名字符串</strong>（如 <code>&quot;Enabled&quot;</code>）。所以选项的 <code>value</code> 必须用成员名才能与表格行数据匹配；整数值放在 <code>valueText</code> 备用。</p></div><h2 id="时区" tabindex="-1">时区 <a class="header-anchor" href="#时区" aria-label="Permalink to &quot;时区&quot;">​</a></h2><ul><li>前端在请求拦截器里发 <strong><code>X-Timezone</code></strong> 头（用户已选时区优先，否则跟随浏览器 <code>Intl</code>）。</li><li>后端<strong>存储恒 UTC</strong>，输出时按该头换算。</li><li>用户可在偏好里选时区。</li></ul><p>所以「时间显示差几小时」的排查顺序是：请求有没有带这个头 → 用户选的时区对不对 → 后端存的是不是 UTC。</p><h2 id="图标-iconify-离线模式" tabindex="-1">图标：Iconify 离线模式 <a class="header-anchor" href="#图标-iconify-离线模式" aria-label="Permalink to &quot;图标：Iconify 离线模式&quot;">​</a></h2><p>图标走 Iconify <strong>离线模式</strong>（<code>~/iconify/offline.ts</code>），用法 <code>&lt;Icon icon=&quot;lucide:eye&quot; /&gt;</code>。</p><div class="danger custom-block"><p class="custom-block-title">只有预加载的图标集能直接用</p><p>运行期直接渲染只保证 <strong><code>lucide</code> / <code>tabler</code> / <code>mdi</code> / <code>simple-icons</code></strong> 这四个已预加载集。未预加载的集（carbon / ep / heroicons 等）在页面里直接用会<strong>渲染为空</strong>——离线 <code>Icon</code> 对已挂载组件不会因后加载而重渲染。</p><p>品牌图标优先用 <code>simple-icons:*</code> 或 <code>tabler:brand-*</code>（如 Gitee 用 <code>simple-icons:gitee</code>）。以仓库的 <code>PRELOAD_ICON_PACKAGES</code> 配置为准。</p></div><p><code>IconPicker</code> 组件可以按需懒加载 carbon / ep / heroicons 供用户选择——那是选择器场景，与「页面里直接渲染」不同。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./../architecture/frontend">前端架构</a>：分层与启动引导</li><li><a href="./schema-page">Schema 驱动页面</a>：<code>dictionaryCode</code> 的用法</li><li><a href="./../api-guide#json-序列化约定">接口对接指南</a>：枚举与时间的序列化规则</li><li><a href="./../faq#页面整片白屏-控制台报-invalid-linked-format">常见问题</a>：白屏与图标空白的处置</li></ul>`,38)])])}const u=o(c,[["render",s]]);export{g as __pageData,u as default};
